properties.property:
[
{
   "text": "Inside this unassuming cave, you see a handful of shady, cloaked figures. They seem to be running some sort of market for powerful spells - the prices are high but the power is undeniable.",
   "options": [{
      "name": "(Continue)", "action": [{"deleteMapObject":-1}]}]
}
]

[
{
   "text": "Separate from the others, a lone figure stands off in an alcove. They call out softly as you approach.

'You want true power? I have a spell here which the ancient mages banned from ever being cast. Don't ask how I got it, but it can be yours... if you have the gold.'",
   "options": [{
      "name": "(Continue)", "action": [{"deleteMapObject":-1}]}]
}
]

[
  {
    "text": "'The forbidden spell I'm selling is Natural Order. Sacrifice a green creature and turn it into any other - something small into the fiercest creatures to exist.'",
    "options": [
      {
        "name": "Let's shake on it. (Spend 100,0000 gold)",
        "condition": [
          { "hasGold": 100000 }
        ],
        "text": "'Pleasure doing business with you.'",
        "action": [
          {
            "addGold": -100000,
            "grantRewards": [
              { "type": "card", "cardName": "Natural Order", "count": 1 }
            ],
		"deleteMapObject":-1
          }
        ]
      },
      {
        "name": "Let's shake on it. (Spend 100,0000 gold)",
        "condition": [
          { "hasGold": 100000, "not": true }
        ],
        "text": "'You're cash shy, friend. Come back when you've gotten a lot more gold.'",
					"options": [ { "name": "(Continue)" } ]
      },
				{
					"name": "Too rich for my blood",
					"text": "'If you're lucky, I'll still be here when you change your mind.'",
					"options": [ { "name": "(Continue)" } ]
				}
    ]
  }
]

[
  {
    "text": "'I have two powerful tutors to find what you need. Survival of the Fittest can repeatedly discard creatures to find new better ones and Finale of Devastation can get any creature into play and with enough mana provide a devastating boost to your forces.'",
    "options": [
      {
        "name": "I want the Survival of the Fittest. (Spend 20,0000 gold)",
        "condition": [
          { "hasGold": 20000 }
        ],
        "text": "'Pleasure doing business with you.'",
        "action": [
          {
            "addGold": -20000,
            "grantRewards": [
              { "type": "card", "cardName": "Survival of the Fittest", "count": 1 }
            ]
          }
        ]
      },
      {
        "name": "I want the Survival of the Fittest. (Spend 20,0000 gold)",
        "condition": [
          { "hasGold": 20000, "not": true }
        ],
        "text": "'No gold, no sale.'",
					"options": [ { "name": "(Continue)" } ]
      },
      {
        "name": "I want the Finale of Devastation. (Spend 20,0000 gold)",
        "condition": [
          { "hasGold": 20000 }
        ],
        "text": "'Pleasure doing business with you.'",
        "action": [
          {
            "addGold": -20000,
            "grantRewards": [
              { "type": "card", "cardName": "Finale of Devastation", "count": 1 }
            ]
          }
        ]
      },
      {
        "name": "I want the Finale of Devastation. (Spend 20,0000 gold)",
        "condition": [
          { "hasGold": 20000, "not": true }
        ],
        "text": "'No gold, no sale.'",
					"options": [ { "name": "(Continue)" } ]
      },
				{
					"name": "Perhaps some other time.",
					"text": "'Come back with heavier pockets.'",
					"options": [ { "name": "(Continue)" } ]
				}
    ]
  }
]

[
